# 3. శతక మాధుర్యం (te3) – Telugu_01T.pdf పేజీలు 16–19
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))
from qbh import Bank, AR, PY, PV, NN, SD, SM, VY
B = Bank(3, 'te3'); q, m = B.q, B.mcq
PP = 'కింది పద్యానికి ప్రతిపదార్థాలు రాయండి.\n'
q(1, 8, PP + 'పలుచని నీచమానవుఁడు పాటిఁ దలంపక నిష్ఠురోక్తులం\nబలుకుచునుండుఁగాని మతిభాసురుఁడైన గుణ ప్రపూర్ణుఁ డ\nప్పలుకులఁ బల్కఁబోవఁడు నిబద్ధిగ నెట్లన వెల్తికుండ దాఁ\nదొలఁకుచు నుండుఁగాని మఱి దొల్కునె నిండుఘటంబు భాస్కరా!',
  'ప్రతిపదార్థం:\nభాస్కరా = ఓ సూర్యదేవా!\nపలుచని = అల్పుడైన (చులకన స్వభావం గల)\nనీచమానవుఁడు = నీచుడైన మనిషి\nపాటిన్ = తగినదానిని (మర్యాదను)\nతలంపక = ఆలోచించకుండా\nనిష్ఠుర + ఉక్తులన్ = కఠినమైన మాటలను\nపలుకుచున్ + ఉండున్ + కాని = మాట్లాడుతూ ఉంటాడు కానీ\nమతిభాసురుఁడు + ఐన = బుద్ధిచేత ప్రకాశించేవాడైన\nగుణ ప్రపూర్ణుఁడు = మంచి గుణాలతో నిండినవాడు\nఆ పలుకులన్ = అటువంటి (కఠినమైన) మాటలను\nనిబద్ధిగన్ = ఎప్పటికీ (నియమంగా)\nపల్కఁబోవఁడు = మాట్లాడడు\nఎట్లు + అనన్ = ఎలాగంటే\nవెల్తికుండ = నీరు తక్కువగా ఉన్న కుండ\nతాన్ = తాను\nతొలఁకుచున్ + ఉండున్ + కాని = తొణుకుతూ ఉంటుంది కానీ\nమఱి = మరి\nనిండుఘటంబు = నిండుగా ఉన్న కుండ\nతొల్కునె = తొణుకుతుందా? (తొణకదు)\nభావం: సగం నిండిన కుండ తొణుకుతుంది, నిండు కుండ తొణకదు. అలాగే అల్పుడు కఠినంగా మాట్లాడతాడు; జ్ఞానవంతుడు, సద్గుణుడు ఎప్పుడూ పరుషంగా మాట్లాడడు. (మారద వెంకయ్య – భాస్కర శతకం)')
q(1, 8, 'విద్యావంతులు ఎటువంటి గుణాలను కలిగి ఉంటారు? (శతక మాధుర్యం ఆధారంగా)',
  '1) మృదువుగా మాట్లాడతారు: నిండుకుండ తొణకనట్లు జ్ఞానవంతులు, సద్గుణులు ఎప్పుడూ కఠినంగా మాట్లాడరు (భాస్కర శతకం).\n2) వినయం: జ్ఞానం పెరిగే కొద్దీ గర్వం తగ్గుతుంది; తామే అన్నీ తెలిసినవారమనే అహంకారం ఉండదు (సుభాషిత రత్నావళి).\n3) నీతి నిష్ఠ: నిందించినా, పొగిడినా, సంపద పోయినా, మరణం వచ్చినా ధీరులు న్యాయమార్గాన్ని విడువరు.\n4) శ్రమించే గుణం: శ్రమే సర్వానికి మూలమని నమ్మి కష్టపడతారు (వేమన).\n5) మంచి ఆలోచన – మంచి మాట – మంచి పని: భావం, మాట, పని, ఫలితం ఒకదాని నొకటి అనుసరిస్తాయని తెలిసి మంచినే ఆలోచిస్తారు (భావలింగ శతకం).\n6) మాతృభాష, మాతృదేశం పట్ల ప్రేమ (కుప్పుస్వామి శతకం).\n7) సత్సంగం: మంచివారి స్నేహం కోరుకుంటారు; తాము కూడా ఇతరులను మంచి మార్గంలో నడిపిస్తారు.\n8) సంతృప్తి, శాంతం, దానగుణం, శౌర్యం వంటి సద్గుణాలు కలిగి ఉంటారు (వేంకటేశ శతకం).\nముగింపు: విద్య వల్ల వినయం, వినయం వల్ల గౌరవం వస్తాయి – నిజమైన విద్యావంతుడు సమాజానికి ఆదర్శం.')
q(1, 8, 'మీ పాఠశాలలో నిర్వహించే పద్యాల పోటీలో విద్యార్థులందరూ పాల్గొనాలని కోరుతూ ఒక ప్రకటన రాయండి.',
  '📢 పద్య పఠన పోటీ – ప్రకటన 📢\nజిల్లా పరిషత్ ఉన్నత పాఠశాల, టి.వి. పల్లి, గూడూరు మండలం, SPSR నెల్లూరు జిల్లా\nప్రియమైన విద్యార్థులారా!\nతెలుగు భాషా వైభవాన్ని, శతక పద్యాల మాధుర్యాన్ని ప్రచారం చేయడానికి మన పాఠశాలలో “శతక పద్య పఠన పోటీ” నిర్వహిస్తున్నాం.\n• తేదీ: xx-xx-20xx (శనివారం)  • సమయం: ఉదయం 10 గంటలకు  • వేదిక: పాఠశాల సమావేశ మందిరం\n• విభాగాలు: 6–7 తరగతులు (జూనియర్), 8–10 తరగతులు (సీనియర్)\nనియమాలు:\n1) ప్రతి విద్యార్థి వేమన, భాస్కర, సుమతి, శ్రీకాళహస్తీశ్వర వంటి ఏవైనా శతకాల నుండి 5 పద్యాలు భావంతో సహా రాగయుక్తంగా చెప్పాలి.\n2) స్పష్టమైన ఉచ్చారణ, భావ వ్యక్తీకరణ, జ్ఞాపకశక్తి ఆధారంగా మార్కులు.\n3) పేర్లు తేదీ xx-xx-20xx లోగా తెలుగు ఉపాధ్యాయులకు ఇవ్వాలి.\nబహుమతులు: ప్రతి విభాగంలో ప్రథమ, ద్వితీయ, తృతీయ బహుమతులు, పాల్గొన్న అందరికీ ప్రశంసాపత్రాలు.\nవిద్యార్థులందరూ ఉత్సాహంగా పాల్గొని తెలుగు పద్య వైభవాన్ని చాటండి!\nఇట్లు,\nప్రధానోపాధ్యాయులు, తెలుగు విభాగం.')
m(1, 'కానలలో క్రూరమృగాలు ఉంటాయి. (గీత గీసిన పదం: కానలు) అర్థం గుర్తించండి.', ['అడవి', 'జంతువు', 'నీరు', 'చెరువు'], 0, mk=2)
m(1, 'పండితుని ఖ్యాతి ప్రపంచమంతటా విస్తరిస్తుంది. (గీత గీసిన పదం: ఖ్యాతి) అర్థం గుర్తించండి.', ['ఊరు', 'పాండిత్యం', 'కీర్తి', 'వైఖరి'], 2, mk=2)
for w, a in [('తల్పం', 'పాన్పు, శయ్య, మంచం'), ('దుష్టుడు', 'చెడ్డవాడు'), ('భాస్వంతుడు', 'సూర్యుడు')]:
    q(1, 2, f'‘{w}’ {AR}', a)
m(1, 'కరి రాజును మావటివాడు అదుపులో పెడతాడు. (గీత గీసిన పదం: కరి) పర్యాయపదాలు గుర్తించండి.', ['రాజు, నృపుడు', 'ఏనుగు, తొండం', 'ఏనుగు, హస్తి', 'ఏనుగు, జంతువు'], 2, mk=2)
m(1, 'గగనతలంలో పక్షి విహరిస్తుంది. (గీత గీసిన పదం: పక్షి) పర్యాయపదాలు గుర్తించండి.', ['ఖగం, పులుగు', 'విమానం, రోదసినౌక', 'గబ్బిలం, జతుక', 'పక్షము, రెక్క'], 0, mk=2)
m(1, 'కలువలకు మిత్రుడు చందురుడు. (గీత గీసిన పదం: చందురుడు) ప్రకృతిని గుర్తించండి.', ['సూర్యుడు', 'ఇంద్రుడు', 'చంద్రుడు', 'ఇందుడు'], 2, mk=2)
m(1, 'నిత్యము అభ్యాసం చేస్తే మంచి ఫలితాలు వస్తాయి. (గీత గీసిన పదం: నిత్యము) వికృతిని గుర్తించండి.', ['నిత్తెము', 'నిదానము', 'నిచ్చలు', 'అనిత్యము'], 2, mk=2)
